import type { EditorState } from "@rich-editor-auy/core";

export interface MountOptions {
  readonly state: EditorState;
  readonly onChange?: (state: EditorState) => void;
  readonly editable?: boolean;
}

export interface MountedEditor {
  destroy(): void;
  view(): HTMLElement;
  dispatch(state: EditorState): void;
}

interface SavedHost {
  readonly html: string;
  readonly editable: string | null;
  readonly role: string | null;
  readonly multiline: string | null;
}

export function mount(host: HTMLElement, options: MountOptions): MountedEditor {
  const saved: SavedHost = {
    html: host.innerHTML,
    editable: host.getAttribute("contenteditable"),
    role: host.getAttribute("role"),
    multiline: host.getAttribute("aria-multiline"),
  };
  host.setAttribute("role", "textbox");
  host.setAttribute("aria-multiline", "true");
  host.setAttribute("contenteditable", options.editable === false ? "false" : "true");
  host.dataset.auyRoot = "true";
  let state = options.state;

  const render = (): void => {
    const parsed = JSON.parse(state.doc().toJSON()) as {
      content?: readonly { type?: string; content?: readonly { type?: string; text?: string }[] }[];
    };
    const nodes = (parsed.content ?? []).map((block, index) => {
      const element = block.type === "heading" ? document.createElement("h2") : document.createElement("p");
      element.dataset.auyPos = String(index);
      const text = (block.content ?? [])
        .map((inline) => (inline.type === "text" ? inline.text ?? "" : ""))
        .join("");
      element.textContent = text;
      return element;
    });
    host.replaceChildren(...nodes);
  };

  const onInput = (): void => {
    options.onChange?.(state);
  };
  host.addEventListener("input", onInput);
  render();

  return {
    destroy(): void {
      host.removeEventListener("input", onInput);
      host.innerHTML = saved.html;
      if (saved.editable === null) host.removeAttribute("contenteditable");
      else host.setAttribute("contenteditable", saved.editable);
      if (saved.role === null) host.removeAttribute("role");
      else host.setAttribute("role", saved.role);
      if (saved.multiline === null) host.removeAttribute("aria-multiline");
      else host.setAttribute("aria-multiline", saved.multiline);
      delete host.dataset.auyRoot;
    },
    view(): HTMLElement {
      return host;
    },
    dispatch(next: EditorState): void {
      state = next;
      render();
    },
  };
}
EOF
