<?php

declare(strict_types=1);

namespace RichEditorAuy;

final class Envelope
{
    public function __construct(
        public readonly string $format,
        public readonly int $version,
        public readonly string $schemaFingerprint,
        public readonly array $doc,
    ) {
    }

    public function requireCompatible(string $schemaFingerprint): void
    {
        if ($this->format !== 'rich-editor-auy' || $this->version !== 1) {
            throw new \InvalidArgumentException('incompatible envelope format');
        }
        if (!preg_match('/^[0-9a-f]{64}$/', $this->schemaFingerprint)) {
            throw new \InvalidArgumentException('schema_fingerprint must be 64 lowercase hex characters');
        }
        if ($this->schemaFingerprint !== $schemaFingerprint) {
            throw new \InvalidArgumentException('schema fingerprint mismatch');
        }
    }
}
EOF
cat > packages/php/src/Document.php <<'EOF'
<?php

declare(strict_types=1);

namespace RichEditorAuy;

final class Document
{
    private function __construct(
        private readonly string $bytes,
        private readonly array $json,
        private readonly Envelope $envelope,
    ) {
    }

    public static function fromBytes(string $bytes): self
    {
        $json = json_decode($bytes, true, 512, JSON_THROW_ON_ERROR);
        if (!is_array($json)) {
            throw new \InvalidArgumentException('document must be a JSON object');
        }
        $envelope = new Envelope(
            is_string($json['format'] ?? null) ? $json['format'] : '',
            is_int($json['version'] ?? null) ? $json['version'] : 0,
            is_string($json['schema_fingerprint'] ?? null) ? $json['schema_fingerprint'] : '',
            is_array($json['doc'] ?? null) ? $json['doc'] : [],
        );
        return new self($bytes, $json, $envelope);
    }

    public function bytes(): string
    {
        return $this->bytes;
    }

    public function json(): array
    {
        return $this->json;
    }

    public function envelope(): Envelope
    {
        return $this->envelope;
    }
}
EOF
cat > packages/php/src/Validator.php <<'EOF'
<?php

declare(strict_types=1);

namespace RichEditorAuy;

final class Validator
{
    public function __construct(private readonly string $binary)
    {
    }

    /** @return array{exit:int,stdout:string,stderr:string} */
    public function validate(string $bytes): array
    {
        $process = proc_open(
            [$this->binary, 'validate'],
            [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']],
            $pipes,
        );
        if (!is_resource($process)) {
            throw new \RuntimeException('could not start validator');
        }
        fwrite($pipes[0], $bytes);
        fclose($pipes[0]);
        $stdout = stream_get_contents($pipes[1]);
        $stderr = stream_get_contents($pipes[2]);
        fclose($pipes[1]);
        fclose($pipes[2]);
        $exit = proc_close($process);
        return ['exit' => $exit, 'stdout' => $stdout === false ? '' : $stdout, 'stderr' => $stderr === false ? '' : $stderr];
    }
}
EOF
